import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, f32

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry layernorm_fwd(
    .param .u64 x_ptr,
    .param .u64 gamma_ptr,
    .param .u64 beta_ptr,
    .param .u64 y_ptr,
    .param .u32 batch,
    .param .u32 feat,
    .param .u32 dim1,
    .param .u32 dim2,
    .param .f32 eps
)
{
    .reg .pred %p_oob, %p_done, %p_done2, %p_lane0, %p_lane0b, %p_warp0, %p_take, %p_donev, %p_done_tail, %p_donev2, %p_done2_tail;
    .reg .b32 %r_batch, %r_feat, %r_dim1, %r_dim2, %r_M;
    .reg .b32 %r_b, %r_tid, %r_bdim, %r_i, %r_lane, %r_warp, %r_tmp, %r_num_warps;
    .reg .b32 %t0, %t1, %r_M4, %r_i4, %r_tail_base;
    .reg .b64 %rd_x, %rd_gamma, %rd_beta, %rd_y;
    .reg .b64 %rd_base_elems, %rd_base_bytes, %rd_x_base, %rd_y_base;
    .reg .b64 %rd_off_i, %rd_addr_xi, %rd_addr_yi, %rd_addr_gi, %rd_addr_bi;
    .reg .b64 %rd_sbase_sum, %rd_sbase_sumsq, %rd_addr_s, %rd_addr_ss, %rd_off_sh;
    .reg .b64 %rd_addr3, %rd_addr4, %rd_off2, %rd_off_v4;
    .reg .f32 %f_eps, %f_sum, %f_sumsq, %f_val, %f_tmp, %f_tmp2;
    .reg .f32 %f_M, %f_mean, %f_var, %f_var_eps, %f_sqrt, %f_invstd, %f_one;
    .reg .f32 %f_gamma, %f_beta, %f_sub, %f_mul, %f_out;
    .reg .f32 %f_x0, %f_x1, %f_x2, %f_x3, %f_g0, %f_g1, %f_g2, %f_g3, %f_b0, %f_b1, %f_b2, %f_b3, %f_o0, %f_o1, %f_o2, %f_o3;
    .shared .align 4 .f32 s_red_sum[32];
    .shared .align 4 .f32 s_red_sumsq[32];
    // Load parameters
    ld.param.u64 %rd_x,      [x_ptr];
    ld.param.u64 %rd_gamma,  [gamma_ptr];
    ld.param.u64 %rd_beta,   [beta_ptr];
    ld.param.u64 %rd_y,      [y_ptr];
    ld.param.u32 %r_batch,   [batch];
    ld.param.u32 %r_feat,    [feat];
    ld.param.u32 %r_dim1,    [dim1];
    ld.param.u32 %r_dim2,    [dim2];
    ld.param.f32 %f_eps,     [eps];
    // Compute M = feat * dim1 * dim2
    mul.lo.u32 %r_M, %r_feat, %r_dim1;
    mul.lo.u32 %r_M, %r_M, %r_dim2;
    // Block index as batch id
    mov.u32 %r_b, %ctaid.x;
    setp.ge.u32 %p_oob, %r_b, %r_batch;
    @%p_oob bra L_RET;
    // Base element offset and byte pointers
    mul.wide.u32 %rd_base_elems, %r_b, %r_M;        // 64-bit elements
    shl.b64 %rd_base_bytes, %rd_base_elems, 2;      // *4 for bytes
    add.s64 %rd_x_base, %rd_x, %rd_base_bytes;
    add.s64 %rd_y_base, %rd_y, %rd_base_bytes;
    // Thread info
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bdim, %ntid.x;
    // Initialize accumulators
    mov.f32 %f_sum, 0f00000000;
    mov.f32 %f_sumsq, 0f00000000;
    // Compute vectorized chunk count M4 = M / 4
    shr.u32 %r_M4, %r_M, 2;
    // Vectorized first pass: compute sum and sumsq in float4
    mov.u32 %r_i4, %r_tid;
L_LOOP_SUM_V4:
    setp.ge.u32 %p_donev, %r_i4, %r_M4;
    @%p_donev bra L_AFTER_SUM_V4;
    // off = i4 * 16 bytes
    mul.wide.u32 %rd_off_v4, %r_i4, 16;
    add.s64 %rd_addr_xi, %rd_x_base, %rd_off_v4;
    ld.global.cg.v4.f32 {%f_x0, %f_x1, %f_x2, %f_x3}, [%rd_addr_xi];
    // accumulate
    add.f32 %f_sum, %f_sum, %f_x0;
    fma.rn.f32 %f_sumsq, %f_x0, %f_x0, %f_sumsq;
    add.f32 %f_sum, %f_sum, %f_x1;
    fma.rn.f32 %f_sumsq, %f_x1, %f_x1, %f_sumsq;
    add.f32 %f_sum, %f_sum, %f_x2;
    fma.rn.f32 %f_sumsq, %f_x2, %f_x2, %f_sumsq;
    add.f32 %f_sum, %f_sum, %f_x3;
    fma.rn.f32 %f_sumsq, %f_x3, %f_x3, %f_sumsq;
    add.u32 %r_i4, %r_i4, %r_bdim;
    bra L_LOOP_SUM_V4;
L_AFTER_SUM_V4:
    // Scalar tail for remaining elements (if M % 4 != 0)
    shl.b32 %r_tail_base, %r_M4, 2; // tail_base = M4 * 4 elements
    add.u32 %r_i, %r_tail_base, %r_tid;
L_LOOP_SUM:
    setp.ge.u32 %p_done, %r_i, %r_M;
    @%p_done bra L_AFTER_SUM;
    mul.wide.u32 %rd_off_i, %r_i, 4;
    add.s64 %rd_addr_xi, %rd_x_base, %rd_off_i;
    ld.global.cg.f32 %f_val, [%rd_addr_xi];
    // accumulate
    fma.rn.f32 %f_sumsq, %f_val, %f_val, %f_sumsq;
    add.f32 %f_sum, %f_sum, %f_val;
    add.u32 %r_i, %r_i, %r_bdim;
    bra L_LOOP_SUM;
L_AFTER_SUM:
    // Warp reduction using shfl for sum
    mov.u32 %r_lane, %laneid;
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 16, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 8, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 4, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 2, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 1, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    // Warp reduction for sumsq
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 16, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 8, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 4, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 2, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 1, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    // Store per-warp results to shared memory by lane 0
    mov.u32 %r_tmp, %tid.x;
    shr.u32 %r_warp, %r_tmp, 5;
    mov.u64 %rd_sbase_sum, s_red_sum;
    mov.u64 %rd_sbase_sumsq, s_red_sumsq;
    mul.wide.u32 %rd_off_sh, %r_warp, 4;
    setp.eq.u32 %p_lane0, %r_lane, 0;
    add.s64 %rd_addr_s, %rd_sbase_sum, %rd_off_sh;
    @%p_lane0 st.shared.f32 [%rd_addr_s], %f_sum;
    add.s64 %rd_addr_ss, %rd_sbase_sumsq, %rd_off_sh;
    @%p_lane0 st.shared.f32 [%rd_addr_ss], %f_sumsq;
    // Sync before final reduction
    bar.sync 0;
    // Compute number of warps
    mov.u32 %r_tmp, %ntid.x;
    add.u32 %r_tmp, %r_tmp, 31;
    shr.u32 %r_num_warps, %r_tmp, 5;
    // Final reduction by warp 0
    setp.eq.u32 %p_warp0, %r_warp, 0;
    @!%p_warp0 bra L_SKIP_FINAL_REDUCE;
    setp.lt.u32 %p_take, %r_lane, %r_num_warps;
    @%p_take mul.wide.u32 %rd_off2, %r_lane, 4;
    @%p_take add.s64 %rd_addr3, %rd_sbase_sum, %rd_off2;
    @%p_take ld.shared.f32 %f_sum, [%rd_addr3];
    @%p_take add.s64 %rd_addr4, %rd_sbase_sumsq, %rd_off2;
    @%p_take ld.shared.f32 %f_sumsq, [%rd_addr4];
    @!%p_take mov.f32 %f_sum, 0f00000000;
    @!%p_take mov.f32 %f_sumsq, 0f00000000;
    // Reduce within warp 0
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 16, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 8, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 4, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 2, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 1, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 16, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 8, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 4, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 2, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 1, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;
    // Write final totals to shared[0]
    setp.eq.u32 %p_lane0b, %r_lane, 0;
    @%p_lane0b st.shared.f32 [%rd_sbase_sum], %f_sum;
    @%p_lane0b st.shared.f32 [%rd_sbase_sumsq], %f_sumsq;
L_SKIP_FINAL_REDUCE:
    bar.sync 0;
    // Load final totals
    ld.shared.f32 %f_sum, [%rd_sbase_sum];
    ld.shared.f32 %f_sumsq, [%rd_sbase_sumsq];
    // Compute mean and inv-std
    cvt.rn.f32.u32 %f_M, %r_M;
    div.rn.f32 %f_mean, %f_sum, %f_M;
    div.rn.f32 %f_var, %f_sumsq, %f_M;
    mul.f32 %f_tmp, %f_mean, %f_mean;
    sub.f32 %f_var, %f_var, %f_tmp;
    add.f32 %f_var_eps, %f_var, %f_eps;
    // Use fast reciprocal sqrt to compute inv-std
    rsqrt.approx.f32 %f_invstd, %f_var_eps;
    // Recompute M4 and tail base for output pass
    shr.u32 %r_M4, %r_M, 2;
    shl.b32 %r_tail_base, %r_M4, 2;
    // Second pass: write normalized output (vectorized)
    mov.u32 %r_i4, %r_tid;
L_LOOP_OUT_V4:
    setp.ge.u32 %p_donev2, %r_i4, %r_M4;
    @%p_donev2 bra L_AFTER_OUT_V4;
    mul.wide.u32 %rd_off_v4, %r_i4, 16;
    // Load x
    add.s64 %rd_addr_xi, %rd_x_base, %rd_off_v4;
    ld.global.cg.v4.f32 {%f_x0, %f_x1, %f_x2, %f_x3}, [%rd_addr_xi];
    // Load gamma
    add.s64 %rd_addr_gi, %rd_gamma, %rd_off_v4;
    ld.global.v4.f32 {%f_g0, %f_g1, %f_g2, %f_g3}, [%rd_addr_gi];
    // Load beta
    add.s64 %rd_addr_bi, %rd_beta, %rd_off_v4;
    ld.global.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%rd_addr_bi];
    // Compute and store y
     // elem 0
     sub.f32 %f_sub, %f_x0, %f_mean;
     mul.f32 %f_mul, %f_sub, %f_invstd;
     fma.rn.f32 %f_o0, %f_mul, %f_g0, %f_b0;
     // elem 1
     sub.f32 %f_sub, %f_x1, %f_mean;
     mul.f32 %f_mul, %f_sub, %f_invstd;
     fma.rn.f32 %f_o1, %f_mul, %f_g1, %f_b1;
     // elem 2
     sub.f32 %f_sub, %f_x2, %f_mean;
     mul.f32 %f_mul, %f_sub, %f_invstd;
     fma.rn.f32 %f_o2, %f_mul, %f_g2, %f_b2;
     // elem 3
     sub.f32 %f_sub, %f_x3, %f_mean;
     mul.f32 %f_mul, %f_sub, %f_invstd;
     fma.rn.f32 %f_o3, %f_mul, %f_g3, %f_b3;
     // Store
     add.s64 %rd_addr_yi, %rd_y_base, %rd_off_v4;
     st.global.v4.f32 [%rd_addr_yi], {%f_o0, %f_o1, %f_o2, %f_o3};
     add.u32 %r_i4, %r_i4, %r_bdim;
    bra L_LOOP_OUT_V4;
L_AFTER_OUT_V4:
    // Scalar tail for output
    add.u32 %r_i, %r_tail_base, %r_tid;
L_LOOP_OUT:
    setp.ge.u32 %p_done2, %r_i, %r_M;
    @%p_done2 bra L_AFTER_OUT;
    mul.wide.u32 %rd_off_i, %r_i, 4;
    add.s64 %rd_addr_xi, %rd_x_base, %rd_off_i;
    ld.global.cg.f32 %f_val, [%rd_addr_xi];
    add.s64 %rd_addr_gi, %rd_gamma, %rd_off_i;
    ld.global.f32 %f_gamma, [%rd_addr_gi];
    add.s64 %rd_addr_bi, %rd_beta, %rd_off_i;
    ld.global.f32 %f_beta, [%rd_addr_bi];
     sub.f32 %f_sub, %f_val, %f_mean;
     mul.f32 %f_mul, %f_sub, %f_invstd;
     fma.rn.f32 %f_out, %f_mul, %f_gamma, %f_beta;
    add.s64 %rd_addr_yi, %rd_y_base, %rd_off_i;
    st.global.f32 [%rd_addr_yi], %f_out;
    add.u32 %r_i, %r_i, %r_bdim;
    bra L_LOOP_OUT;
L_AFTER_OUT:
L_RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layernorm_fwd")

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        B, F, D1, D2 = x.shape
        y = torch.empty_like(x)
        module = _get_ptx_module()
        block_x = 1024
        grid_x = B
        module.launch(
            "layernorm_fwd",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x, self.weight, self.bias, y,
                i32(B), i32(F), i32(D1), i32(D2), f32(self.eps)
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

